package com.yeshoda.medical.controller; import com.yeshoda.medical.model.Doctor; import com.yeshoda.medical.repository.DoctorRepository; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/doctors") public class DoctorController {private final DoctorRepository r;public DoctorController(DoctorRepository r){this.r=r;} @GetMapping public List<Doctor> all(@RequestParam(required=false) String specialty){return specialty==null||specialty.isBlank()?r.findAll():r.findBySpecialtyContainingIgnoreCase(specialty);} @GetMapping("/{id}") public Doctor one(@PathVariable Long id){return r.findById(id).orElseThrow();}}
